===================================================================
--- a/src/scene.js
+++ b/src/scene.js
@@ -1,25 +1,53 @@
 // Preserve every semantic object, material, geometry, animation and picking identity.
 // semanticId identifies an ordinary mesh; semanticIds identifies each instance.
 export function createWorld(THREE, scene) {
   const count = 1600;
-  const robots = [];
-  for (let i = 0; i < count; i++) {
-    const geometry = new THREE.BoxGeometry(.72, .48, .94);
-    const material = new THREE.MeshStandardMaterial({color: i % 3 === 0 ? 0xf59b52 : 0x4f8ca8, roughness: .42, metalness: .35});
-    const mesh = new THREE.Mesh(geometry, material);
-    mesh.userData.semanticId = 'robot-' + i;
-    scene.add(mesh);
-    robots.push(mesh);
+  const geometry = new THREE.BoxGeometry(.72, .48, .94);
+  const matA = new THREE.MeshStandardMaterial({color: 0xf59b52, roughness: .42, metalness: .35});
+  const matB = new THREE.MeshStandardMaterial({color: 0x4f8ca8, roughness: .42, metalness: .35});
+  const idxA = [];
+  const idxB = [];
+  for (let i = 0; i < count; i++) { (i % 3 === 0 ? idxA : idxB).push(i); }
+  const meshA = new THREE.InstancedMesh(geometry, matA, idxA.length);
+  const meshB = new THREE.InstancedMesh(geometry, matB, idxB.length);
+  meshA.frustumCulled = false;
+  meshB.frustumCulled = false;
+  meshA.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
+  meshB.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
+  meshA.userData.semanticIds = idxA.map(i => 'robot-' + i);
+  meshB.userData.semanticIds = idxB.map(i => 'robot-' + i);
+  scene.add(meshA);
+  scene.add(meshB);
+  const locA = new Map();
+  const locB = new Map();
+  idxA.forEach((g, k) => locA.set(g, k));
+  idxB.forEach((g, k) => locB.set(g, k));
+  const _p = new THREE.Vector3();
+  const _q = new THREE.Quaternion();
+  const _e = new THREE.Euler();
+  const _s = new THREE.Vector3(1, 1, 1);
+  const _m = new THREE.Matrix4();
+  function writeAt(i, x, y, z, rotY) {
+    _p.set(x, y, z);
+    _e.set(0, rotY, 0);
+    _q.setFromEuler(_e);
+    _m.compose(_p, _q, _s);
+    if (i % 3 === 0) meshA.setMatrixAt(locA.get(i), _m);
+    else meshB.setMatrixAt(locB.get(i), _m);
   }
   return {
     update(t) {
       for (let i = 0; i < count; i++) {
         const column = i % 40;
         const row = Math.floor(i / 40);
-        const position = new THREE.Vector3((column - 19.5) * 1.25, .32 + Math.sin(t * 1.8 + i * .13) * .04, (row - Math.floor(count / 40) / 2) * 1.3 + Math.sin(t * .4 + column * .2) * .4);
-        robots[i].position.copy(position);
-        robots[i].rotation.y = Math.sin(t * .5 + i * .04) * .18;
+        const x = (column - 19.5) * 1.25;
+        const y = .32 + Math.sin(t * 1.8 + i * .13) * .04;
+        const z = (row - Math.floor(count / 40) / 2) * 1.3 + Math.sin(t * .4 + column * .2) * .4;
+        const rotY = Math.sin(t * .5 + i * .04) * .18;
+        writeAt(i, x, y, z, rotY);
       }
+      meshA.instanceMatrix.needsUpdate = true;
+      meshB.instanceMatrix.needsUpdate = true;
     }
   };
 }
